var files = Folder("~/shoot").getFiles(/\.(jpe?g|tif|psd)$/i);
var o = new ContactSheetOptions();
o.width = 2400; o.height = 2900; o.resolution = 300;  // px cap 2900
o.columnCount = 4; o.rowCount = 5; o.useAutoSpacing = true;
o.mode = NewDocumentMode.RGB; o.flatten = false; o.bestFit = true;
o.caption = true; o.font = GalleryFontType.HELVETICA; o.fontSize = 9;
app.makeContactSheet(files, o);  // legacy native call: test in 27.x first

var doc = app.activeDocument;
var ci = doc.countItems.add([UnitValue(120, "px"), UnitValue(80, "px")]);
alert(doc.countItems.length + " marked; last at x=" + ci.position[0].as("px"));
for (var i = doc.countItems.length - 1; i >= 0; i--) {
  if (doc.countItems[i].position[0].as("px") < 50) doc.countItems[i].remove();
}
